// Header implements http.ResponseWriter.
func (c *captured) Header() http.Header { return c.header }

// WriteHeader implements http.ResponseWriter.
func (c *captured) WriteHeader(status int) {
	if c.status == 0 {
		c.status = status
	}
}

// Write implements http.ResponseWriter.
func (c *captured) Write(b []byte) (int, error) {
	c.WriteHeader(http.StatusOK)
	return c.body.Write(b)
}

// writeKept sends an answer: its status, its headers and its body.
func writeKept(w http.ResponseWriter, status int, header http.Header, body []byte) {
	for k, vs := range header {
		w.Header()[k] = vs
	}
	w.WriteHeader(status)
	_, _ = w.Write(body)
}

// idempotencyKey reads the Idempotency-Key header: "" when there is none. A key that is not 1 to 255 printable ASCII
// characters is answered 400 and returns false.
func idempotencyKey(w http.ResponseWriter, r *http.Request) (string, bool) {
	vs := r.Header.Values("Idempotency-Key")
	if len(vs) == 0 {
		return "", true
	}
	if k := vs[0]; len(vs) == 1 && len(k) >= 1 && len(k) <= 255 && printableASCII(k) {
		return k, true
	}
	writeError(w, http.StatusBadRequest, "invalid_idempotency_key", "Idempotency-Key is 1 to 255 printable ASCII characters")
	return "", false
}

// printableASCII reports whether s holds only characters from space (0x20) to tilde (0x7E).
func printableASCII(s string) bool {
	for i := 0; i < len(s); i++ {
		if s[i] < 0x20 || s[i] > 0x7e {
			return false
		}
	}
	return true
}

// payWithKey handles a pay request that sent an Idempotency-Key. The first request with a key is answered, and its answer
// is kept unless it is a 5xx; a later request with the key gets that answer back without charging again.
func (s *Server) payWithKey(w http.ResponseWriter, r *http.Request, p auth.Principal, key, invoiceID, paymentMethod string) {
	k := idemKey{orgID: p.OrgID, key: key}
	e, state := s.idem.begin(k, invoiceID, paymentMethod, s.clock.Now())
	switch state {
	case idemReused:
		writeError(w, http.StatusUnprocessableEntity, "idempotency_key_reused", "this Idempotency-Key was used for another invoice or body")
		return
	case idemInProgress:
		writeError(w, http.StatusConflict, "request_in_progress", "a request with this Idempotency-Key is still being handled")
		return
	case idemReplay:
		w.Header().Set("Idempotent-Replayed", "true")
		writeKept(w, e.status, e.header, e.body)
		return
	}
	c := newCaptured()
	answered := false
	defer func() {
		if !answered {
			s.idem.finish(k, e, nil)
		}
	}()
	s.payOnce(c, r, p, invoiceID, paymentMethod)
	answered = true
	s.idem.finish(k, e, c)
	writeKept(w, c.status, c.header, c.body.Bytes())
}

