func TestPayKeyKeepsDeclinesForADay(t *testing.T) {
	e := apitest.New(t)
	c := e.CreateCustomer(e.Acme, "Jane", "jane@acme.example")
	path := payPath(openInvoice(t, e, e.Acme, c.ID))
