	}
	if n := len(e.Gateway.Calls()); n != 1 {
		t.Fatalf("gateway calls = %d, want 1", n)
	}
	e.Clock.Advance(time.Minute)
	r = e.DoWith("POST", path, e.Acme.Key, body, withKey("declined"))
	if r.Code != http.StatusPaymentRequired || r.Header.Get("Idempotent-Replayed") != "" {
		t.Fatalf("after 24 hours the key is new: %s", r)
	}
	if n := len(e.Gateway.Calls()); n != 2 {
		t.Fatalf("gateway calls = %d, want 2", n)
	}
}

