			t.Fatalf("key %q: %s", key, r)
		}
	}
	if r := e.DoWith("POST", path, e.Acme.Key, body, http.Header{"Idempotency-Key": {"one", "two"}}); r.Code != http.StatusBadRequest {
		t.Fatalf("two keys: %s", r)
	}
}

func TestPayKeysBelongToAnOrganization(t *testing.T) {
	e := apitest.New(t)
	acme := e.CreateCustomer(e.Acme, "Jane", "jane@acme.example")
	globex := e.CreateCustomer(e.Globex, "Joe", "joe@globex.example")
	acmePath := payPath(openInvoice(t, e, e.Acme, acme.ID))
	globexPath := payPath(openInvoice(t, e, e.Globex, globex.ID))
	body := map[string]string{"payment_method": "pm_card_visa"}

	if r := e.DoWith("POST", acmePath, e.Acme.Key, body, withKey("shared")); r.Code != http.StatusOK {
		t.Fatalf("acme: %s", r)
	}
	r := e.DoWith("POST", globexPath, e.Globex.Key, body, withKey("shared"))
	if r.Code != http.StatusOK || r.Header.Get("Idempotent-Replayed") != "" {
		t.Fatalf("globex with the same key: %s", r)
	}
	if n := len(e.Gateway.Charges()); n != 2 {
		t.Fatalf("charges = %d, want 2", n)
	}
}

func TestPayKeyReusedForAnotherInvoiceOrBody(t *testing.T) {
	e := apitest.New(t)
	c := e.CreateCustomer(e.Acme, "Jane", "jane@acme.example")
	first := payPath(openInvoice(t, e, e.Acme, c.ID))
	second := payPath(openInvoice(t, e, e.Acme, c.ID))
	visa := map[string]string{"payment_method": "pm_card_visa"}

	if r := e.DoWith("POST", first, e.Acme.Key, visa, withKey("reuse")); r.Code != http.StatusOK {
		t.Fatalf("first pay: %s", r)
	}
	for _, tc := range []struct {
		name, path string
		body       map[string]string
	}{
		{"another invoice", second, visa},
		{"another body", first, map[string]string{"payment_method": "pm_card_mastercard"}},
	} {
		r := e.DoWith("POST", tc.path, e.Acme.Key, tc.body, withKey("reuse"))
		if r.Code != http.StatusUnprocessableEntity || r.Map(t)["error"] != "idempotency_key_reused" {
			t.Fatalf("%s: %s", tc.name, r)
		}
	}
	if n := len(e.Gateway.Charges()); n != 1 {
		t.Fatalf("charges = %d, want 1", n)
	}
}

func TestPayRefusesAPaymentWhileAnotherIsUnderWay(t *testing.T) {
	e := apitest.New(t)
	c := e.CreateCustomer(e.Acme, "Jane", "jane@acme.example")
	path := payPath(openInvoice(t, e, e.Acme, c.ID))
	body := map[string]string{"payment_method": "pm_card_visa"}

	held := make(chan struct{}, 1)
	release := make(chan struct{})
	e.Gateway.OnCharge = func(payments.ChargeRequest) {
		held <- struct{}{}
		<-release
	}
	answer := make(chan *apitest.Response, 1)
	go func() { answer <- e.DoWith("POST", path, e.Acme.Key, body, withKey("slow")) }()
	<-held

	// The same key while the first request is handled: refused at once, not made to wait.
	if r := e.DoWith("POST", path, e.Acme.Key, body, withKey("slow")); r.Code != http.StatusConflict || r.Map(t)["error"] != "request_in_progress" {
		t.Fatalf("same key while in progress: %s", r)
	}
	// Another key, or no key, for the same invoice: nothing is charged twice.
	if r := e.DoWith("POST", path, e.Acme.Key, body, withKey("other")); r.Code != http.StatusConflict || r.Map(t)["error"] != "payment_in_progress" {
		t.Fatalf("other key while charging: %s", r)
	}
	if r := e.Do("POST", path, e.Acme.Key, body); r.Code != http.StatusConflict || r.Map(t)["error"] != "payment_in_progress" {
		t.Fatalf("no key while charging: %s", r)
	}
	close(release)
	if r := <-answer; r.Code != http.StatusOK {
		t.Fatalf("first pay: %s", r)
	}
	if n := len(e.Gateway.Calls()); n != 1 {
		t.Fatalf("gateway calls = %d, want 1", n)
	}
	if r := e.DoWith("POST", path, e.Acme.Key, body, withKey("slow")); r.Code != http.StatusOK || r.Header.Get("Idempotent-Replayed") != "true" {
		t.Fatalf("replay after the charge: %s", r)
	}
}

func TestPayKeyIsNotKeptForServerErrors(t *testing.T) {
	e := apitest.New(t)
	c := e.CreateCustomer(e.Acme, "Jane", "jane@acme.example")
	path := payPath(openInvoice(t, e, e.Acme, c.ID))
	// With no body, the customer's default payment method is charged, so it can change between tries.
	e.Store.UpdateCustomer(e.Acme.ID, c.ID, func(c *store.Customer) error { c.DefaultPaymentMethod = "pm_gateway_down"; return nil })

	if r := e.DoWith("POST", path, e.Acme.Key, nil, withKey("flaky")); r.Code != http.StatusServiceUnavailable || r.Map(t)["error"] != "gateway_unavailable" {
		t.Fatalf("gateway down: %s", r)
	}
	e.Store.UpdateCustomer(e.Acme.ID, c.ID, func(c *store.Customer) error { c.DefaultPaymentMethod = "pm_card_visa"; return nil })
	r := e.DoWith("POST", path, e.Acme.Key, nil, withKey("flaky"))
	if r.Code != http.StatusOK || r.Header.Get("Idempotent-Replayed") != "" {
		t.Fatalf("retry after a 503 should pay again: %s", r)
	}
	if n := len(e.Gateway.Charges()); n != 1 {
		t.Fatalf("charges = %d, want 1", n)
	}
}

func TestPayKeyKeepsDeclinesForADay(t *testing.T) {
	e := apitest.New(t)
	c := e.CreateCustomer(e.Acme, "Jane", "jane@acme.example")
	path := payPath(openInvoice(t, e, e.Acme, c.ID))
	body := map[string]string{"payment_method": "pm_card_declined"}

	if r := e.DoWith("POST", path, e.Acme.Key, body, withKey("declined")); r.Code != http.StatusPaymentRequired {
		t.Fatalf("first: %s", r)
	}
	e.Clock.Advance(24*time.Hour - time.Minute)
	r := e.DoWith("POST", path, e.Acme.Key, body, withKey("declined"))
	if r.Code != http.StatusPaymentRequired || r.Header.Get("Idempotent-Replayed") != "true" || r.Map(t)["decline_code"] != "card_declined" {
		t.Fatalf("retry within 24 hours: %s", r)
	}
	if n := len(e.Gateway.Calls()); n != 1 {
		t.Fatalf("gateway calls = %d, want 1", n)
	}
	e.Clock.Advance(time.Minute)
	r = e.DoWith("POST", path, e.Acme.Key, body, withKey("declined"))
	if r.Code != http.StatusPaymentRequired || r.Header.Get("Idempotent-Replayed") != "" {
		t.Fatalf("after 24 hours the key is new: %s", r)
	}
	if n := len(e.Gateway.Calls()); n != 2 {
		t.Fatalf("gateway calls = %d, want 2", n)
	}
}

