data.output:
1	// Package payments charges invoices through the payment gateway.
2	package payments
3	
4	import (
5		"context"
6		"errors"
7		"fmt"
8		"sync"
9	
10		"example.com/tally/internal/billing"
11		"example.com/tally/internal/clock"
12		"example.com/tally/internal/money"
13		"example.com/tally/internal/store"
14	)
15	
16	// ChargeRequest asks the gateway to take money from a payment method.
17	type ChargeRequest struct {
18		Amount        int64 // minor units
19		Currency      money.Currency
20		PaymentMethod string // "pm_..."
21		Description   string
22	}
23	
24	// ChargeResult is a successful charge.
25	type ChargeResult struct {
26		Ref string // the gateway's reference, "ch_..."
27	}
28	
29	// Gateway is the payment processor.
30	type Gateway interface {
31		Charge(ctx context.Context, req ChargeRequest) (ChargeResult, error)
32	}
33	
34	// DeclineError is a charge the card's issuer refused. Nothing was taken.
35	type DeclineError struct {
36		Code string // for example "card_declined", "insufficient_funds"
37	}
38	
39	func (e *DeclineError) Error() string { return "card declined: " + e.Code }
40	
41	// Errors.
42	var (
43		// ErrUnavailable means the gateway could not be reached or failed; nothing was taken and the charge may be retried.
44		ErrUnavailable     = errors.New("payment gateway unavailable")
45		ErrAlreadyPaid     = errors.New("the invoice is already paid")
46		ErrInvoiceVoid     = errors.New("the invoice is void")
47		ErrNoPaymentMethod = errors.New("no payment method to charge")
48	
49		// ErrPaymentInProgress means another payment of the same invoice is being charged right now; nothing was charged by this
50		// request.
51		ErrPaymentInProgress = errors.New("a payment for this invoice is already under way")
52	)
53	
54	// Publisher sends events to the organization's webhook endpoints (webhooks.Service).
55	type Publisher interface {
56		Publish(ctx context.Context, orgID, eventType string, data any) error
57	}
58	
59	// Service pays invoices.
60	type Service struct {
61		Store     *store.Store
62		Gateway   Gateway
63		Clock     clock.Clock
64		Publisher Publisher // nil: no events
65	
66		mu       sync.Mutex
67		charging map[invoiceRef]bool // invoices a Pay call is working on
68	}
69	
70	// invoiceRef names one organization's invoice.
71	type invoiceRef struct{ orgID, invoiceID string }
72	
73	// Pay charges an open invoice's total to paymentMethod, or to the customer's default payment method when it is empty, and
74	// marks the invoice paid. An invoice whose total is zero or less is marked paid without a charge. A declined charge is
75	// recorded as a failed payment and returned as a *DeclineError; when the gateway is unavailable nothing is recorded and the
76	// error wraps ErrUnavailable. While one Pay call works on an invoice, another for the same invoice returns
77	// ErrPaymentInProgress at once, so an invoice is never charged twice.
78	func (s *Service) Pay(ctx context.Context, orgID, invoiceID, paymentMethod string) (store.Invoice, store.Payment, error) {
79		if !s.begin(invoiceRef{orgID, invoiceID}) {
80			return store.Invoice{}, store.Payment{}, ErrPaymentInProgress
81		}
82		defer s.end(invoiceRef{orgID, invoiceID})
83		inv, ok := s.Store.Invoice(orgID, invoiceID)
84		if !ok {
85			return store.Invoice{}, store.Payment{}, store.ErrNotFound
86		}
87		switch inv.Status {
88		case store.InvoicePaid:
89			return inv, store.Payment{}, ErrAlreadyPaid
90		case store.InvoiceVoid:
91			return inv, store.Payment{}, ErrInvoiceVoid
92		}
93		total := billing.Compute(inv).Total
94		if total <= 0 {
95			inv, err := s.markPaid(ctx, inv, store.Payment{})
96			return inv, store.Payment{}, err
97		}
98		if paymentMethod == "" {
99			if c, ok := s.Store.Customer(orgID, inv.CustomerID); ok {
100				paymentMethod = c.DefaultPaymentMethod
101			}
102		}
103		if paymentMethod == "" {
104			return inv, store.Payment{}, ErrNoPaymentMethod
105		}
106		res, err := s.Gateway.Charge(ctx, ChargeRequest{Amount: total, Currency: inv.Currency, PaymentMethod: paymentMethod, Description: "Invoice " + inv.ID})
107		var decline *DeclineError
108		switch {
109		case errors.As(err, &decline):
110			p, perr := s.Store.CreatePayment(store.Payment{OrgID: orgID, InvoiceID: inv.ID, Amount: total, Currency: inv.Currency, Status: store.PaymentFailed, FailureCode: decline.Code}, s.Clock.Now())
111			if perr != nil {
112				return inv, store.Payment{}, perr
113			}
114			s.publish(ctx, orgID, "invoice.payment_failed", map[string]any{"invoice_id": inv.ID, "payment_id": p.ID, "failure_code": decline.Code})
115			return inv, p, err
116		case err != nil:
117			if errors.Is(err, ErrUnavailable) {
118				return inv, store.Payment{}, err
119			}
120			return inv, store.Payment{}, fmt.Errorf("%w: %v", ErrUnavailable, err)
121		}
122		p, err := s.Store.CreatePayment(store.Payment{OrgID: orgID, InvoiceID: inv.ID, Amount: total, Currency: inv.Currency, Status: store.PaymentSucceeded, GatewayRef: res.Ref}, s.Clock.Now())
123		if err != nil {
124			return inv, store.Payment{}, err
125		}
126		inv, err = s.markPaid(ctx, inv, p)
127		return inv, p, err
128	}
129	
